const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function arenaPage(d,ui){
  const {active,statusText,heading,formatSpeech,sourceCard,review,assistantPanel,rightCollapsed,rightTab}=ui;
  const resumable=['failed','cancelled','interrupted'].includes(d.status);
  const controls=`<div class="arena-actions">${active?'<button class="primary" id="cancel">中止辩论</button>':resumable?'<button class="primary" id="resume-debate">继续辩论</button>':'<button class="secondary" id="again">再辩一场 →</button>'}<a class="secondary" href="/api/debates/${d.id}/export">导出记录 ↓</a>${!active?`<button class="secondary danger" data-delete-debate="${d.id}">删除本场</button>`:''}</div>`;
  return `${heading('THE ARENA',esc(d.topic),`${d.language==='en'?'English':'中文'} · ${d.agents.length} 位辩手 · ${d.rounds} 轮交锋 · ${statusText[d.status]}`,controls)}<section class="arena-overview"><div><strong>${active?'辩论正在进行':resumable?'辩论已中止，可接着进行':'本场辩论已结束'}</strong><p>${active?'中止会保留已完成发言；继续时从未完成的发言接着生成。':resumable?'已完成的发言与资料保留。继续辩论不会重写已有发言。':'查看赛后评审，或让教练结合本场记录制定练习。'}</p></div><div class="arena-review-links"><button class="secondary" data-jump-review ${d.review?'':'disabled'}>${d.review?'查看赛后评审与点评 ↓':d.status==='judging'?'评审正在生成…':'赛后评审待生成'}</button><button class="secondary" data-open-coach="debate">教练复盘与练习 ↗</button></div></section><div class="arena-toolbar"><span>发言记录 · ${d.messages.length} 条</span><div><button class="text-button" id="toggle-voice">${ui.autoVoice?'自动朗读：开':'自动朗读：关'}</button><button class="text-button" id="stop-voice">停止朗读</button><button class="secondary" id="toggle-arena-sidebar" aria-expanded="${!rightCollapsed}" aria-controls="arena-sidebar">${rightCollapsed?'展开分析与资料 ‹':'收起右侧栏 ›'}</button></div></div><div class="arena-layout ${rightCollapsed?'right-collapsed':''}"><section class="transcript" aria-label="辩论发言记录"><div class="section-heading"><h2>辩论记录</h2><span class="live ${active?'pulsing':''}">${statusText[d.status]}</span></div>${d.mode==='demo'?'<div class="notice">演示内容为固定模板；连接模型后生成真实论证和分析。</div>':''}${d.error?`<div class="notice error">${esc(d.error)}</div>`:''}${d.messages.map(m=>`<article class="speech" id="speech-${m.id}"><div class="speech-head"><div class="avatar ${m.side}">${esc(m.name.slice(0,1))}</div><strong>${esc(m.name)}</strong><span class="side-tag ${m.side}">${m.side==='pro'?'正方':'反方'}</span><span class="speech-stage">${esc(m.stage)}${m.round?' · 第 '+m.round+' 轮':''}</span></div><div class="speech-body">${formatSpeech(m.content,d.sources)}</div><div class="speech-tools"><button class="text-button" data-attach-speech="${m.id}">＋ 问分析助手</button><button class="read-button" data-read="${m.id}" aria-label="朗读 ${esc(m.name)} 的发言">♩ 朗读</button></div></article>`).join('')||'<div class="empty compact"><p>辩手正在准备，完成的发言将依次显示在这里。</p></div>'}${active?`<div class="thinking"><span class="thinking-dots">● ● ●</span> ${esc(d.current?.name||'研究助理')} · ${esc(d.current?.stage||'准备')}…</div>`:''}${d.review?`<div id="arena-verdict" tabindex="-1">${review(d.review)}<div class="review-next"><strong>把点评变成下一步练习</strong><p>教练会读取本场快照，帮助你修改立论、反驳和表达。</p><button class="primary" data-open-coach="debate">进入教练复盘与练习 →</button></div></div>`:''}</section>${rightCollapsed?'':`<aside class="research-panel arena-sidebar" id="arena-sidebar"><div class="arena-side-tabs" role="group" aria-label="现场侧栏内容"><button data-arena-side="assistant" aria-pressed="${rightTab==='assistant'}">分析 Agent</button><button data-arena-side="sources" aria-pressed="${rightTab==='sources'}">共享资料 · ${d.sources.length}</button></div>${rightTab==='assistant'?assistantPanel(d):`<section><h2>共享资料</h2><p class="hint">引用链接可查看来源；搜索摘要不等于核验后的事实。</p>${d.sources.map(sourceCard).join('')||'<p class="hint">本场尚无外部资料。</p>'}${d.researchLog?.length?`<details class="warnings"><summary>检索进度</summary>${d.researchLog.map(r=>`<p>${esc(r.agent)} · ${esc(r.status)}</p>`).join('')}</details>`:''}${d.warnings.length?`<details class="warnings"><summary>运行提示 · ${d.warnings.length}</summary>${d.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}</details>`:''}</section>`}</aside>`}</div>`;
}
